create or replace function public.erp_hr_validate_company_links() returns trigger language plpgsql set search_path=public as $$ begin if tg_table_name='erp_hr_recruitment_candidates' then if new.job_id is not null and not exists(select 1 from public.erp_hr_jobs j where j.id=new.job_id and j.company_id=new.company_id) then raise exception 'الوظيفة المحددة لا تتبع الشركة الحالية.'; end if; else if not exists(select 1 from public.erp_employees e where e.id=new.employee_id and e.company_id=new.company_id) then raise exception 'الموظف المحدد لا يتبع الشركة الحالية.'; end if; end if; return new; end; $$; drop trigger if exists trg_hr_compliance_company_link on public.erp_hr_employee_compliance; create trigger trg_hr_compliance_company_link before insert or update of company_id,employee_id on public.erp_hr_employee_compliance for each row execute function public.erp_hr_validate_company_links(); drop trigger if exists trg_hr_training_company_link on public.erp_hr_training_records; create trigger trg_hr_training_company_link before insert or update of company_id,employee_id on public.erp_hr_training_records for each row execute function public.erp_hr_validate_company_links(); drop trigger if exists trg_hr_candidate_company_link on public.erp_hr_recruitment_candidates; create trigger trg_hr_candidate_company_link before insert or update of company_id,job_id on public.erp_hr_recruitment_candidates for each row execute function public.erp_hr_validate_company_links(); drop trigger if exists trg_hr_movement_company_link on public.erp_hr_employee_movements; create trigger trg_hr_movement_company_link before insert or update of company_id,employee_id on public.erp_hr_employee_movements for each row execute function public.erp_hr_validate_company_links();